// device-sync — single-file build for the Supabase dashboard (generated by tools/bundle.py; edit supabase/functions/ instead)

import { createClient } from 'npm:@supabase/supabase-js@2';

// ---- shared/logic ----
// Pure helpers (no network / no Deno APIs) so they can be unit-tested.

type Task = { id: string; kind: 'daily' | 'weekly' | 'once'; weekdays: number[] | null };

/** 0 = Sunday ... 6 = Saturday, for a 'YYYY-MM-DD' string (timezone independent). */
function weekdayOf(day: string): number {
  return new Date(day + 'T00:00:00Z').getUTCDay();
}

function prevDay(day: string): string {
  const d = new Date(day + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().slice(0, 10);
}

function isValidDay(day: unknown): day is string {
  return typeof day === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(day) && !isNaN(Date.parse(day));
}

type Schedule = {
  type?: 'daily' | 'weekdays' | 'monthly' | 'interval' | 'once';
  weekdays?: number[]; month_day?: number; every_n?: number; date?: string;
  start?: string | null; end?: string | null;
} | null;

function dayOfMonth(day: string): number { return Number(day.slice(8, 10)); }
function lastDayOfMonth(day: string): number {
  const y = Number(day.slice(0, 4)), m = Number(day.slice(5, 7));
  return new Date(Date.UTC(y, m, 0)).getUTCDate();
}
function daysBetween(a: string, b: string): number {
  return Math.round((Date.parse(b + 'T00:00:00Z') - Date.parse(a + 'T00:00:00Z')) / 864e5);
}

/** Is this task due on `day`? Old tasks (no schedule) use kind/weekdays; new ones use the schedule. */
function isDueOn(t: { kind: string; weekdays: number[] | null; schedule?: Schedule }, day: string, hasLogEver: boolean): boolean {
  const s = t.schedule;
  if (!s || !s.type) {
    if (t.kind === 'daily') return true;
    if (t.kind === 'weekly') return (t.weekdays ?? []).includes(weekdayOf(day));
    if (t.kind === 'once') return !hasLogEver;
    return false;
  }
  if (s.start && day < s.start) return false;
  if (s.end && day > s.end) return false;
  switch (s.type) {
    case 'daily': return true;
    case 'weekdays': return (s.weekdays ?? []).includes(weekdayOf(day));
    case 'monthly': return dayOfMonth(day) === Math.min(s.month_day ?? 1, lastDayOfMonth(day));
    case 'interval': {
      if (!s.start) return false;
      const diff = daysBetween(s.start, day);
      return diff >= 0 && diff % Math.max(1, s.every_n ?? 1) === 0;
    }
    case 'once': return s.date === day && !hasLogEver;
  }
  return false;
}

/** Task templates that need a log row on this day. */
function dueTasks<T extends { id: string; kind: string; weekdays: number[] | null; schedule?: Schedule }>(tasks: T[], day: string, hasLogEver: Set<string>): T[] {
  return tasks.filter(t => isDueOn(t, day, hasLogEver.has(t.id)));
}

/** AI score is 0..20; points scale linearly with it. */
function scaledPoints(base: number, score: number, max = 20): number {
  const s = Math.max(0, Math.min(max, score));
  return Math.round((base * s) / max);
}

function shouldAutoApprove(score: number, threshold: number | null | undefined): boolean {
  return threshold != null && score >= threshold;
}

/** Daily bonus: only if the phone actually reported that day (else a dead phone would earn points). */
function bonusFor(kid: { bonus_under_min: number | null; bonus_points: number }, totalMinutes: number, hadReport: boolean): number {
  if (!hadReport || kid.bonus_under_min == null || kid.bonus_points <= 0) return 0;
  return totalMinutes < kid.bonus_under_min ? kid.bonus_points : 0;
}

/** Pull the first JSON object out of a model reply (tolerates ```json fences and chatter). */
function parseJsonLoose(text: string): any | null {
  const clean = text.replace(/```json|```/g, '');
  const start = clean.indexOf('{');
  if (start < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < clean.length; i++) {
    const c = clean[i];
    if (inStr) { if (esc) esc = false; else if (c === '\\') esc = true; else if (c === '"') inStr = false; continue; }
    if (c === '"') inStr = true;
    else if (c === '{') depth++;
    else if (c === '}' && --depth === 0) {
      try { return JSON.parse(clean.slice(start, i + 1)); } catch { return null; }
    }
  }
  return null;
}

type Grade = { score: number; feedback: string; readable: boolean };

/** Validate and clamp what the model returned. */
function normalizeGrade(raw: any): Grade | null {
  if (!raw || typeof raw !== 'object') return null;
  const readable = raw.readable !== false;
  const score = Number(raw.score);
  if (readable && !Number.isFinite(score)) return null;
  return {
    readable,
    score: readable ? Math.max(0, Math.min(20, Math.round(score * 2) / 2)) : 0,
    feedback: String(raw.feedback ?? '').slice(0, 600),
  };
}

/** Persian/Arabic digits -> ASCII, strip separators. "۱٬۲۳۴٬۵۰۰" -> 1234500 */
function parsePrice(v: unknown): number | null {
  if (typeof v === 'number') return v > 0 ? Math.round(v) : null;
  if (typeof v !== 'string') return null;
  const ascii = v.replace(/[۰-۹]/g, d => String(d.charCodeAt(0) - 1776)).replace(/[٠-٩]/g, d => String(d.charCodeAt(0) - 1632));
  const n = Number(ascii.replace(/[^\d.]/g, ''));
  return Number.isFinite(n) && n > 0 ? Math.round(n) : null;
}

/** Cheap og:image / og:title extraction from raw HTML. */
function extractMeta(html: string): { title?: string; image?: string } {
  const pick = (prop: string) => {
    const re1 = new RegExp(`<meta[^>]+(?:property|name)=["']${prop}["'][^>]*content=["']([^"']+)["']`, 'i');
    const re2 = new RegExp(`<meta[^>]+content=["']([^"']+)["'][^>]*(?:property|name)=["']${prop}["']`, 'i');
    return (html.match(re1) ?? html.match(re2))?.[1];
  };
  return { title: pick('og:title'), image: pick('og:image') };
}

function isHttpUrl(u: unknown): u is string {
  if (typeof u !== 'string') return false;
  try { const p = new URL(u).protocol; return p === 'http:' || p === 'https:'; } catch { return false; }
}

/** Validate dictation phrases coming from the model or a parent: 1..15 non-empty strings. */
function normalizePhrases(raw: unknown, maxPhrases = 15): string[] {
  if (!Array.isArray(raw)) return [];
  return raw.filter((p): p is string => typeof p === 'string').map(p => p.replace(/\s+/g, ' ').trim().slice(0, 200)).filter(Boolean).slice(0, maxPhrases);
}

function countDictationDoneToday(rows: { status: string; done_day: string | null }[], day: string): number {
  return rows.filter(r => (r.status === 'graded' || r.status === 'done') && r.done_day === day).length;
}

/** Find the last audio block in an Interactions API reply (steps[].content[]). */
function findAudio(res: any): string | null {
  let found: string | null = null;
  for (const st of res?.steps ?? []) for (const c of st?.content ?? []) if (c?.type === 'audio' && typeof c.data === 'string') found = c.data;
  return found;
}

/** Calendar day in Iran (UTC+3:30) of an ISO timestamp. */
function tehranDay(iso: string): string {
  return new Date(Date.parse(iso) + 3.5 * 3600_000).toISOString().slice(0, 10);
}

/** The last n days ending at `day`, oldest first. */
function lastDays(day: string, n = 7): string[] {
  const out = [day];
  for (let i = 1; i < n; i++) out.unshift(prevDay(out[0]));
  return out;
}

/** Points EARNED (positive ledger rows) per day, aligned with `days`. */
function weekPoints(rows: { delta: number; created_at: string }[], days: string[]): number[] {
  const m = new Map(days.map(d => [d, 0]));
  for (const r of rows) if (r.delta > 0) { const d = tehranDay(r.created_at); if (m.has(d)) m.set(d, m.get(d)! + r.delta); }
  return days.map(d => m.get(d)!);
}

/** Kid/parent PINs are 4 to 8 digits. */
function isValidPin(p: unknown): p is string {
  return typeof p === 'string' && /^\d{4,8}$/.test(p);
}

/** AI-made drawing for the tutor's whiteboard. Only plain SVG shapes are allowed; anything risky -> null. */
function cleanSvg(svg: unknown): string | null {
  if (typeof svg !== 'string') return null;
  const s = svg.trim().slice(0, 8000);
  if (!/^<svg[\s>]/i.test(s) || !/<\/svg>$/i.test(s)) return null;
  if (/<\s*(script|foreignobject|iframe|object|embed|image|use|style|link|meta|animate|set)\b/i.test(s)) return null;
  if (/\son[a-z]+\s*=/i.test(s) || /javascript:|data:|https?:/i.test(s)) return null;
  return s;
}

/** Key used for the automatic penalty of one unfinished task on one day (unique per kid). */
function autoPenaltyNote(day: string, taskId: string): string { return `auto:${day}:${taskId}`; }

/** Today's date in Iran (UTC+3:30, no DST). The server must never use UTC for a "day". */
function tehranToday(now: Date = new Date()): string {
  return new Date(now.getTime() + 3.5 * 3600_000).toISOString().slice(0, 10);
}


// ---------------- Lessons from a textbook QR ----------------

/** Hostname is exactly one of the allowed domains or a sub-domain of one. Empty list = nothing allowed. */
function hostAllowed(url: string, allowedCsv: string): boolean {
  let host: string;
  try { host = new URL(url).hostname.toLowerCase(); } catch { return false; }
  const list = allowedCsv.split(',').map(x => x.trim().toLowerCase().replace(/^\./, '')).filter(Boolean);
  return list.some(d => host === d || host.endsWith('.' + d));
}

/** Only public http(s) pages: no credentials, no odd ports, no localhost / private / link-local / IP-literal hosts. */
function isSafePublicUrl(u: unknown): u is string {
  if (typeof u !== 'string' || u.length > 600) return false;
  let p: URL;
  try { p = new URL(u); } catch { return false; }
  if (p.protocol !== 'http:' && p.protocol !== 'https:') return false;
  if (p.username || p.password) return false;
  if (p.port && p.port !== '80' && p.port !== '443') return false;
  const h = p.hostname.toLowerCase();
  if (!h.includes('.') || h.startsWith('[') || /^\d+(\.\d+){3}$/.test(h) || /^\d+$/.test(h)) return false;   // no IP literals / single-label hosts
  if (h === 'localhost' || h.endsWith('.localhost') || h.endsWith('.local') || h.endsWith('.internal') || h.endsWith('.lan') || h.endsWith('.home')) return false;
  return true;
}

type MediaItem = { type: 'video' | 'audio' | 'page'; url: string; title?: string };

/** Find playable media on a page: <video>/<audio>/<source>, direct links, og:video, and known embed iframes. */
function extractMedia(html: string, baseUrl: string, max = 8): MediaItem[] {
  const out: MediaItem[] = [];
  const seen = new Set<string>();
  const add = (raw: string | undefined, type: MediaItem['type'], title?: string) => {
    if (!raw) return;
    let abs: string;
    try { abs = new URL(raw.trim().replace(/&amp;/g, '&'), baseUrl).toString(); } catch { return; }
    if (!isSafePublicUrl(abs) || seen.has(abs) || out.length >= max) return;
    seen.add(abs); out.push({ type, url: abs, ...(title ? { title: title.slice(0, 80) } : {}) });
  };
  const VID = /\.(mp4|webm|m4v|mov|m3u8)(\?|#|$)/i, AUD = /\.(mp3|m4a|aac|ogg|oga|wav)(\?|#|$)/i;
  for (const m of html.matchAll(/<video\b[^>]*\bsrc=["']([^"']+)["']/gi)) add(m[1], 'video');
  for (const m of html.matchAll(/<audio\b[^>]*\bsrc=["']([^"']+)["']/gi)) add(m[1], 'audio');
  for (const m of html.matchAll(/<source\b[^>]*\bsrc=["']([^"']+)["'][^>]*>/gi)) add(m[1], AUD.test(m[1]) || /type=["']audio/i.test(m[0]) ? 'audio' : 'video');
  for (const m of html.matchAll(/<meta[^>]+property=["']og:(video|audio)(?::url|:secure_url)?["'][^>]*content=["']([^"']+)["']/gi)) add(m[2], m[1] === 'audio' ? 'audio' : 'video');
  for (const m of html.matchAll(/<a\b[^>]*\bhref=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
    const t = m[2].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
    if (VID.test(m[1])) add(m[1], 'video', t); else if (AUD.test(m[1])) add(m[1], 'audio', t);
  }
  for (const m of html.matchAll(/<iframe\b[^>]*\bsrc=["']([^"']+)["']/gi)) if (/aparat\.com|youtube\.com\/embed|youtube-nocookie\.com/i.test(m[1])) add(m[1], 'page');
  return out;
}

type Section = { title: string; asked: number; correct: number; done: boolean };

function normalizeSections(raw: unknown, max = 12): Section[] {
  if (!Array.isArray(raw)) return [];
  return raw.map(x => typeof x === 'string' ? x : (x as any)?.title).filter((x): x is string => typeof x === 'string')
    .map(x => x.replace(/\s+/g, ' ').trim().slice(0, 100)).filter(Boolean).slice(0, max)
    .map(title => ({ title, asked: 0, correct: 0, done: false }));
}

/** Record one practice round on a section; a section is done after >= 5 questions with >= 70% correct. */
function applyPractice(sections: Section[], idx: number, correct: number, total: number): Section[] {
  return sections.map((s, i) => {
    if (i !== idx) return s;
    const asked = s.asked + total, ok = s.correct + correct;
    return { ...s, asked, correct: ok, done: s.done || (asked >= 5 && ok / asked >= 0.7) };
  });
}

/** Where to continue: the first section that is not done (or the last one if all are). */
function nextSection(sections: Section[]): number {
  const i = sections.findIndex(s => !s.done);
  return i === -1 ? Math.max(0, sections.length - 1) : i;
}

/** Segments for dictation from audio: sorted, within the audio length, each 0.5s..30s. */
function cleanSegments(raw: unknown, maxSeconds = 3600): { text: string; start: number; end: number }[] {
  if (!Array.isArray(raw)) return [];
  const out: { text: string; start: number; end: number }[] = [];
  for (const r of raw as any[]) {
    const text = typeof r?.text === 'string' ? r.text.replace(/\s+/g, ' ').trim().slice(0, 200) : '';
    const start = Number(r?.start), end = Number(r?.end);
    if (!text || !Number.isFinite(start) || !Number.isFinite(end)) continue;
    if (start < 0 || end > maxSeconds || end - start < 0.5 || end - start > 30) continue;
    if (out.length && start < out[out.length - 1].start) continue;
    out.push({ text, start: Math.round(start * 10) / 10, end: Math.round(end * 10) / 10 });
  }
  return out.slice(0, 15);
}

// ---- Tutor: school lessons vs free (after-school) classes ----
type Track = 'school' | 'free';
const FREE_PREFIX = 'free:';

/** "free" only when asked for explicitly; anything else (including old phones that send nothing) is a school lesson. */
function trackOf(v: unknown): Track { return v === 'free' ? 'free' : 'school'; }

/**
 * The key a subject is stored under. School lessons keep their plain name (so existing data stays where it is);
 * free classes are stored as "free:<name>", so school English and an English-institute class never share a level or plan.
 */
function subjectKey(subject: unknown, track: unknown): string {
  if (typeof subject !== 'string') return '';
  let s = subject.trim().toLowerCase();
  let t = trackOf(track);
  if (s.startsWith(FREE_PREFIX)) { s = s.slice(FREE_PREFIX.length).trim(); t = 'free'; }
  s = s.slice(0, 40);
  if (!s) return '';
  return t === 'free' ? FREE_PREFIX + s : s;
}

/** Stored key -> track and the name shown to the kid / the AI. */
function splitSubject(key: string): { track: Track; name: string } {
  return key.startsWith(FREE_PREFIX) ? { track: 'free', name: key.slice(FREE_PREFIX.length) } : { track: 'school', name: key };
}

/** One line for the AI prompts so the teacher behaves differently in school lessons and free classes. */
function trackHint(track: Track): string {
  return track === 'free'
    ? 'نوع کلاس: کلاس آزاد (فوق‌برنامه، بیرون از مدرسه). به کتاب درسی مدرسه وابسته نباش؛ بر اساس هدف بچه یک مسیر عملی، قدم‌به‌قدم و سرگرم‌کننده بچین و مهارت واقعی را تمرین بده.'
    : 'نوع کلاس: درس مدرسه. مطابق کتاب درسی رسمی مدرسه‌های ایران، با همان ترتیب، اصطلاحات و سطح کتاب پیش برو و برای امتحان مدرسه آماده‌اش کن.';
}

// ---- Tutor: did the kid really learn it? ----
function addDays(day: string, n: number): string {
  const d = new Date(day + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

/** Days until the next review, by stage. Stage 0 = still practicing (again tomorrow); 3 = learned; 4 = solid. */
const REVIEW_GAPS = [1, 3, 7, 21, 60];
type ConceptStatus = 'new' | 'practicing' | 'learned' | 'solid';
type ConceptRow = { stage: number; attempts: number; first_try_correct: number; next_review: string | null };

/** One name per idea, however the AI spells it ("  Fractions " == "fractions"). */
function conceptKey(s: unknown): string {
  return typeof s === 'string' ? s.replace(/\s+/g, ' ').trim().toLowerCase().slice(0, 60) : '';
}

function conceptStatus(stage: number, attempts: number): ConceptStatus {
  return stage >= 4 ? 'solid' : stage >= 3 ? 'learned' : attempts > 0 ? 'practicing' : 'new';
}

function isDue(c: { next_review: string | null }, day: string): boolean {
  return !!c.next_review && c.next_review <= day;
}

/**
 * A graded check on one concept: `correct` of `total` questions, all first tries.
 * It moves the concept up only when the check "counts" — an exit quiz right after the lesson, or a review on/after its due day.
 * Answering right on the same day again does not count (that is short-term memory). Getting most of it wrong sends it back to the start.
 */
function applyConceptResult(c: ConceptRow, correct: number, total: number, day: string, counts: boolean) {
  const ratio = total > 0 ? correct / total : 0;
  let stage = Math.max(0, Math.min(4, c.stage | 0));
  const before = stage;
  if (total > 0 && ratio < 0.5) stage = 0;
  else if (ratio >= 2 / 3 && counts) stage = Math.min(4, stage + 1);
  const attempts = c.attempts + total;
  const next_review = stage !== before || !c.next_review ? addDays(day, REVIEW_GAPS[stage]) : c.next_review;
  return { stage, status: conceptStatus(stage, attempts), next_review, attempts, first_try_correct: c.first_try_correct + correct, last_seen: day, moved: stage - before };
}

const LEVEL_ORDER = ['مبتدی', 'متوسط', 'پیشرفته'];
/** Level follows the last few graded checks (ratios 0..1, newest last): up when ≥85% on average, down when ≤40%. Needs 3+ checks. */
function nextLevel(level: string | null, ratios: number[]): string | null {
  const last = ratios.slice(-5);
  if (last.length < 3 || !level) return level;
  const i = LEVEL_ORDER.indexOf(level);
  if (i < 0) return level;
  const avg = last.reduce((a, b) => a + b, 0) / last.length;
  if (avg >= 0.85 - 1e-9 && i < LEVEL_ORDER.length - 1) return LEVEL_ORDER[i + 1];
  if (avg <= 0.4 + 1e-9 && i > 0) return LEVEL_ORDER[i - 1];
  return level;
}

/** Points: right on the first try is worth the most; right after help is worth less; the exit quiz counts double. */
function answerPoints(correct: boolean, firstTry: boolean, exit = false): number {
  if (!correct) return 0;
  return (firstTry ? 1 : 0) * (exit ? 2 : 1);
}

// ---- Kid wallet ----
type SpendCategory = 'snack' | 'fun' | 'invest';
const SPEND_CATEGORIES: SpendCategory[] = ['snack', 'fun', 'invest'];
const INVEST_GIFT = 0.2;   // parents add 20% of an investment as a gift

/**
 * What a spend costs in points. Snacks and fun/toys: the toman amount in points, rounded up.
 * Investment: the same points are spent, but the parents first give 20% of it as a gift, so the kid's balance drops by 80%.
 */
function spendCost(amountToman: number, tomanPerPoint: number, category: SpendCategory) {
  const rate = tomanPerPoint > 0 ? tomanPerPoint : 1000;
  const points = Math.max(1, Math.ceil(amountToman / rate));
  const gift = category === 'invest' ? Math.round(points * INVEST_GIFT) : 0;
  return { points, gift, net: points - gift };
}

type LedgerSource = 'tasks' | 'dictation' | 'tutor' | 'bonus' | 'gift' | 'invest_gift' | 'penalty' | 'payout' | 'snack' | 'fun' | 'invest' | 'other';

/** Where one ledger row came from, in words a kid understands (labels in the app). */
function ledgerSource(r: { reason: string; delta: number; note?: string | null; category?: string | null }): LedgerSource {
  const note = r.note ?? '';
  switch (r.reason) {
    case 'task':
      if (note.startsWith('دیکته')) return 'dictation';
      if (/^(تمرین معلم|کلاس آزاد|آزمون خروج|جواب روی تخته|یاد دادن)/.test(note)) return 'tutor';
      return 'tasks';
    case 'screen_bonus': return 'bonus';
    case 'manual': return r.delta >= 0 ? 'gift' : 'penalty';
    case 'penalty': return 'penalty';
    case 'payout': return 'payout';
    case 'invest_gift': return 'invest_gift';
    case 'spend': return (SPEND_CATEGORIES as string[]).includes(r.category ?? '') ? (r.category as LedgerSource) : 'other';
    default: return 'other';
  }
}

/** Earned (by source) and spent (by category) totals over ledger rows. */
function walletBreakdown(rows: { reason: string; delta: number; note?: string | null; category?: string | null; amount_toman?: number | null }[]) {
  const earned: Record<string, number> = {}, spent: Record<string, number> = {}, spentToman: Record<string, number> = {};
  let penalties = 0, payouts = 0;
  for (const r of rows) {
    const s = ledgerSource(r);
    if (s === 'penalty') penalties += -r.delta;
    else if (s === 'payout') payouts += -r.delta;
    else if (r.reason === 'spend') { spent[s] = (spent[s] ?? 0) + -r.delta; spentToman[s] = (spentToman[s] ?? 0) + (r.amount_toman ?? 0); }
    else if (r.delta > 0) earned[s] = (earned[s] ?? 0) + r.delta;
  }
  return { earned, spent, spentToman, penalties, payouts, balance: rows.reduce((a, r) => a + r.delta, 0) };
}

// ---- Tutor: reuse what the AI already made ----
/** Answers compared loosely (Persian/Arabic letters and digits, spaces, punctuation, case) so an exact answer needs no AI check. */
function normAnswer(s: unknown): string {
  return String(s ?? '')
    .replace(/[يى]/g, 'ی').replace(/ك/g, 'ک').replace(/[ۀة]/g, 'ه').replace(/[أإآ]/g, 'ا')
    .replace(/[۰-۹]/g, d => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(d))).replace(/[٠-٩]/g, d => String('٠١٢٣٤٥٦٧٨٩'.indexOf(d)))
    .replace(/[ً-ْ‌‏]/g, '')
    .replace(/[.,،؛;:!?؟«»"'()\-_]/g, ' ')
    .replace(/\s+/g, ' ').trim().toLowerCase();
}
function sameAnswer(a: unknown, b: unknown): boolean {
  const x = normAnswer(a), y = normAnswer(b);
  return !!x && x === y;
}

/** From saved items of one kind, the least used one (oldest first on a tie). */
function pickCached<T extends { uses: number; created_at: string }>(rows: T[]): T | null {
  if (!rows.length) return null;
  return rows.slice().sort((a, b) => a.uses - b.uses || a.created_at.localeCompare(b.created_at))[0];
}

function topicKey(text: string): string {
  return 'topic:' + normAnswer(text).slice(0, 120);
}

// ---- Hourly reminder ----
/** What the phone says when tasks are waiting. */
function reminderText(name: string): string {
  return `${String(name ?? '').trim().slice(0, 30)} جان، کارهات منتظرتن. نمیای؟`;
}

// ---- shared/common ----
const cors = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
};

const json = (body: unknown, status = 200) =>
  new Response(JSON.stringify(body), { status, headers: { ...cors, 'Content-Type': 'application/json' } });

const admin = () =>
  createClient(Deno.env.get('SUPABASE_URL')!, Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!, {
    auth: { persistSession: false, autoRefreshToken: false },
  });

async function sha256(s: string): Promise<string> {
  const buf = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(s));
  return [...new Uint8Array(buf)].map(b => b.toString(16).padStart(2, '0')).join('');
}

/** Device phones authenticate with a long random token (only its hash is stored). */
// deno-lint-ignore no-explicit-any
async function authDevice(db: any, token: unknown) {
  if (typeof token !== 'string' || token.length < 16 || token.length > 200) return null;
  const { data } = await db.from('devices').select('*').eq('token_hash', await sha256(token)).maybeSingle();
  return data ?? null;
}

// ---- function ----
// deno-lint-ignore-file no-explicit-any
Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: cors });
  if (req.method !== 'POST') return json({ error: 'method_not_allowed' }, 405);
  let body: any;
  try { body = await req.json(); } catch { return json({ error: 'bad_json' }, 400); }

  const db = admin();
  const device = await authDevice(db, body.token);
  if (!device) return json({ error: 'unauthorized' }, 401);
  const day = body.day;
  if (!isValidDay(day)) return json({ error: 'bad_day' }, 400);

  const { data: kids } = await db.from('kids').select('*').eq('active', true).order('name');
  const kidIds = new Set<string>((kids ?? []).map((k: any) => k.id));

  // 1) usage reported by the phone (absolute minutes for today, so retries are idempotent)
  const rows: any[] = [];
  for (const [kidId, pk] of Object.entries(body.usage ?? {})) {
    if (!kidIds.has(kidId)) continue;
    for (const [pkg, min] of Object.entries(pk as Record<string, number>)) {
      const m = Math.round(Number(min));
      if (pkg.length < 200 && m >= 0 && m <= 1440) rows.push({ kid_id: kidId, day, package_name: pkg, minutes: m });
    }
  }
  if (rows.length) await db.from('usage_logs').upsert(rows, { onConflict: 'kid_id,day,package_name' });

  // 2) installed apps (so the parent can choose which are allowed)
  const apps = (Array.isArray(body.apps) ? body.apps : []).slice(0, 1500)
    .filter((a: any) => typeof a?.package_name === 'string')
    .map((a: any) => ({ device_id: device.id, package_name: a.package_name, label: String(a.label ?? '').slice(0, 80) }));
  if (apps.length) await db.from('device_apps').upsert(apps, { onConflict: 'device_id,package_name' });
  await db.from('devices').update({ last_seen: new Date().toISOString() }).eq('id', device.id);

  // 3) make sure today's task rows exist
  const { data: tasks } = await db.from('tasks').select('*').eq('active', true);
  const onceIds = (tasks ?? []).filter((t: any) => t.kind === 'once').map((t: any) => t.id);
  const seen = new Set<string>();
  if (onceIds.length) {
    const { data: l } = await db.from('task_logs').select('task_id').in('task_id', onceIds);
    (l ?? []).forEach((r: any) => seen.add(r.task_id));
  }
  const due = dueTasks((tasks ?? []).filter((t: any) => kidIds.has(t.kid_id)), day, seen);
  if (due.length) {
    await db.from('task_logs').upsert(
      due.map((t: any) => ({ task_id: t.id, kid_id: t.kid_id, due_date: day })),
      { onConflict: 'task_id,due_date', ignoreDuplicates: true },
    );
  }

  // 4) yesterday's low-screen-time bonus (one per kid per day, enforced by a unique index)
  const y = prevDay(day);
  const { data: yu } = await db.from('usage_logs').select('kid_id,minutes').eq('day', y);
  for (const k of kids ?? []) {
    const mine = (yu ?? []).filter((r: any) => r.kid_id === k.id);
    const pts = bonusFor(k, mine.reduce((a: number, r: any) => a + r.minutes, 0), mine.length > 0);
    if (pts > 0) await db.from('points_ledger').insert({ kid_id: k.id, delta: pts, reason: 'screen_bonus', note: `bonus:${y}` }); // 23505 on repeat is fine
  }

  // 4b) automatic penalty: yesterday's unfinished tasks cost their penalty points, only for kids who turned it on.
  //      The unique index on points_ledger(kid_id, note) makes repeated syncs harmless.
  const { data: yLogs } = await db.from('task_logs').select('task_id,kid_id,status,tasks(penalty_points)').eq('due_date', y);
  for (const log of yLogs ?? []) {
    const k = (kids ?? []).find((x: any) => x.id === log.kid_id);
    if (!k || !(k as any).auto_penalty) continue;
    if (log.status !== 'pending' && log.status !== 'rejected') continue;
    const pts = (log as any).tasks?.penalty_points ?? 0;
    if (pts > 0) await db.from('points_ledger').insert({ kid_id: k.id, delta: -pts, reason: 'penalty', note: `auto:${y}:${log.task_id}` });
  }

  // penalties the kid should see: manual ones applied today, and yesterday's automatic one
  const { data: manualToday } = await db.from('penalty_logs').select('kid_id,points,penalty_rules(title)').eq('day', day);
  const { data: autoRows } = await db.from('points_ledger').select('kid_id,delta,note').eq('reason', 'penalty').like('note', `auto:${y}:%`);
  const titleOf: Record<string, string> = Object.fromEntries((tasks ?? []).map((t: any) => [t.id, t.title]));

  // 5) state for the phone
  const [{ data: logs }, { data: ledger }, { data: rules }, { data: wish }, { data: st }, { data: cmds }, { data: ut }, { data: dicts }] = await Promise.all([
    db.from('task_logs').select('id,kid_id,status,ai_score,ai_feedback,points_awarded,tasks(title,points,needs_photo,subject)').eq('due_date', day),
    db.from('points_ledger').select('kid_id,delta,created_at'),
    db.from('app_rules').select('*'),
    db.from('wishlist_progress').select('id,kid_id,title,image_url,price_toman,points_needed,points_left'),
    db.from('settings').select('*').single(),
    db.from('device_commands').select('*').eq('device_id', device.id).eq('done', false),
    db.from('usage_logs').select('kid_id,package_name,minutes').eq('day', day),
    db.from('dictations').select('id,kid_id,title,status,points,phrases,ai_score,ai_feedback,points_awarded,done_day,audio_url,segments'),
  ]);
  if (cmds?.length) await db.from('device_commands').update({ done: true }).in('id', cmds.map((c: any) => c.id));

  const bal: Record<string, number> = {};
  (ledger ?? []).forEach((r: any) => { bal[r.kid_id] = (bal[r.kid_id] ?? 0) + r.delta; });
  const usage: Record<string, Record<string, number>> = {};
  (ut ?? []).forEach((r: any) => { (usage[r.kid_id] ??= {})[r.package_name] = r.minutes; });

  const days = lastDays(day, 7);
  const screenMin = (kidId: string) => {
    const edu = new Set((rules ?? []).filter((r: any) => r.kid_id === kidId && r.category === 'edu').map((r: any) => r.package_name));
    return Object.entries(usage[kidId] ?? {}).filter(([pkg]) => !edu.has(pkg)).reduce((a, [, m]) => a + m, 0);
  };

  return json({
    day,
    week_days: days,
    toman_per_point: st?.toman_per_point ?? 1000,
    kids: (kids ?? []).map((k: any) => ({
      id: k.id, name: k.name, pin_hash: k.pin_hash, daily_limit_min: k.daily_limit_min,
      reminder_on: k.reminder_on ?? true, reminder_quiet: k.reminder_quiet ?? '23-10,14-18',
      balance: bal[k.id] ?? 0,
      week_points: weekPoints((ledger ?? []).filter((r: any) => r.kid_id === k.id), days),
      screen_min_today: screenMin(k.id),
      penalties: [
        ...(manualToday ?? []).filter((r: any) => r.kid_id === k.id).map((r: any) => ({ title: r.penalty_rules?.title ?? 'جریمه', points: r.points })),
        ...(autoRows ?? []).filter((r: any) => r.kid_id === k.id).map((r: any) => ({ title: 'کار ناتمام دیروز: ' + (titleOf[String(r.note).split(':')[2]] ?? ''), points: -r.delta })),
      ],
      tasks: (logs ?? []).filter((l: any) => l.kid_id === k.id).map((l: any) => ({
        log_id: l.id, title: l.tasks.title, points: l.tasks.points, needs_photo: l.tasks.needs_photo,
        status: l.status, ai_score: l.ai_score, ai_feedback: l.ai_feedback, points_awarded: l.points_awarded,
      })),
      wishlist: (wish ?? []).filter((w: any) => w.kid_id === k.id),
      rules: (rules ?? []).filter((r: any) => r.kid_id === k.id),
      dictations: (dicts ?? []).filter((d: any) => d.kid_id === k.id && (d.status === 'review' || d.status === 'ready' || d.done_day === day))
        .map((d: any) => ({ id: d.id, title: d.title, status: d.status, points: d.points, phrase_count: (d.phrases ?? []).length, ai_score: d.ai_score, ai_feedback: d.ai_feedback, points_awarded: d.points_awarded, audio_url: d.audio_url ?? null, segments: d.segments ?? null })),
    })),
    usage_today: usage,
    commands: (cmds ?? []).map((c: any) => ({ command: c.command, payload: c.payload })),
  });
});
